#!/bin/bash
# Publish the loose files the updater downloads, and the manifest that points
# at them. Developer-only - a tester never sees this.
#
#   ./publish-update.sh rooms-beta-9 /path/to/unpacked/PeppyDolphin-beta
#
# The zip on the release page stays as it is, for somebody installing for the
# first time. These three loose assets are what "Update Peppy.exe" fetches, so
# an existing folder only pulls what actually changed - usually 24 KB or 161 KB
# rather than 12 MB.
#
# ⚠️ The manifest lives on the BRANCH, not on a release, because a release tag
# moves every time and the updater needs one address that never changes.
# Committing it is what makes an update go live.
set -e

TAG="$1"
PKG="$2"
[ -n "$TAG" ] && [ -n "$PKG" ] || { echo "usage: $0 <tag> <package-dir>"; exit 1; }
[ -d "$PKG" ] || { echo "no such folder: $PKG"; exit 1; }

REPO="attunegames/peppy-dolphin"
BASE="https://github.com/$REPO/releases/download/$TAG"
DIST="$(cd "$(dirname "$0")" && pwd)"

# local path inside the folder | the asset name on the release
# ⚠️ Asset names carry no spaces: GitHub rewrites them, and the updater would
# then ask for a URL that does not exist.
FILES=(
  "Slippi Dolphin.exe|SlippiDolphin.exe"
  "Sys/GameSettings/GALE01r2.ini|GALE01r2.ini"
  "Sys/GameFiles/GALE01/SlippiRoom.dat|SlippiRoom.dat"
)

echo "uploading loose files to $TAG"
for entry in "${FILES[@]}"; do
  rel="${entry%%|*}"; asset="${entry##*|}"
  [ -f "$PKG/$rel" ] || { echo "  MISSING $rel"; exit 1; }
  cp "$PKG/$rel" "/tmp/$asset"
  gh release upload "$TAG" "/tmp/$asset" -R "$REPO" --clobber >/dev/null
  echo "  $asset  $(md5sum "$PKG/$rel" | cut -c1-8)"
done

{
  echo "# Peppy Dolphin - what the updater checks against."
  echo "#"
  echo "# One line per file:  file <path>|<first 8 of md5>|<url>"
  echo "# The path is relative to the folder Slippi Dolphin.exe sits in."
  echo "#"
  echo "# Generated by publish-update.sh - do not hand-edit."
  echo "version $TAG"
  for entry in "${FILES[@]}"; do
    rel="${entry%%|*}"; asset="${entry##*|}"
    hash="$(md5sum "$PKG/$rel" | cut -c1-8)"
    # Backslashes, because the updater hands this straight to CreateFile.
    win="${rel//\//\\}"
    echo "file $win|$hash|$BASE/$asset"
  done
} > "$DIST/latest.txt"

echo
echo "wrote $DIST/latest.txt:"
sed 's/^/    /' "$DIST/latest.txt"
echo
echo "⚠️  Commit and push latest.txt - that is what makes the update go live."
